using System;
using System.IO;
using System.Linq;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;
using System.Collections.Generic;
using System.Web.Script.Serialization;
internal static class GanymedeReader {
 internal const string Site="https://ganymede-app.com";
 static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=TougliReader.MaxBytes,RecursionLimit=64};
 internal static bool IsGuide(string slug){return Regex.IsMatch(slug??"",@"^ganymede-[1-9][0-9]{0,8}$");}
 internal static string GuideSlug(string value){var m=Regex.Match((value??"").Trim(),@"^(?:https://ganymede-app\.com/guides/)?([1-9][0-9]{0,8})/?(?:\?[^#\s]*)?(?:#[^\s]*)?$");if(!m.Success)throw new InvalidDataException("Indiquez un numéro de guide ou un lien https://ganymede-app.com/guides/123.");return "ganymede-"+m.Groups[1].Value;}
 internal static string Url(string slug){if(!IsGuide(slug))throw new InvalidDataException("Guide Ganymède invalide.");return Site+"/guides/"+slug.Substring(9);}
 static object Page(string html){if(Encoding.UTF8.GetByteCount(html)>TougliReader.MaxBytes)throw new InvalidDataException("Page Ganymède trop volumineuse.");var script=Regex.Match(html,@"<script\b[^>]*\bdata-page\s*=\s*[""']app[""'][^>]*>([\s\S]*?)</script>",RegexOptions.IgnoreCase,TimeSpan.FromSeconds(2));if(script.Success)return Json.DeserializeObject(script.Groups[1].Value);var legacy=Regex.Match(html,@"<div\b[^>]*\bdata-page\s*=\s*""([^""]+)""",RegexOptions.IgnoreCase,TimeSpan.FromSeconds(2));if(legacy.Success)return Json.DeserializeObject(WebUtility.HtmlDecode(legacy.Groups[1].Value));throw new InvalidDataException("La page publique Ganymède n’a pas le format attendu.");}
 internal static List<TougliGuideInfo> Catalogue(string html){var props=TougliReader.Get(Page(html),"props");var nodes=TougliReader.Get(props,"nodes");if(nodes==null)throw new InvalidDataException("La liste publique Ganymède n’est pas disponible.");return TougliReader.Arr(nodes).Where(n=>!Object.Equals(TougliReader.Get(n,"hidden"),1)).Select(n=>TougliReader.Get(TougliReader.Get(n,"guides"),"fr")).Where(g=>g!=null).Select(g=>new TougliGuideInfo{Slug="ganymede-"+TougliReader.S(TougliReader.Get(g,"id")),Title="Ganymède · "+TougliReader.Plain(TougliReader.Get(g,"name"))}).Where(g=>IsGuide(g.Slug)).GroupBy(g=>g.Slug).Select(g=>g.First()).OrderBy(g=>g.Title).ToList();}
 internal static string Normalise(string html){var guide=TougliReader.Get(TougliReader.Get(Page(html),"props"),"guide");if(guide==null)throw new InvalidDataException("Ce lien ne contient pas de guide public.");var steps=TougliReader.Arr(TougliReader.Get(guide,"steps"));if(steps.Length<1||steps.Length>10000)throw new InvalidDataException("Nombre d’étapes Ganymède invalide.");return Json.Serialize(new{ganymedeGuide=new{id=TougliReader.Get(guide,"id"),name=TougliReader.Get(guide,"name"),description=TougliReader.Get(guide,"web_description")??TougliReader.Get(guide,"description"),author=TougliReader.Get(TougliReader.Get(guide,"user"),"name"),steps=steps.Select(s=>new{id=TougliReader.Get(s,"id"),name=TougliReader.Get(s,"name"),text=TougliReader.Get(s,"web_text")??TougliReader.Get(s,"text"),order=TougliReader.Get(s,"order"),map=TougliReader.Get(s,"map"),pos_x=TougliReader.Get(s,"pos_x"),pos_y=TougliReader.Get(s,"pos_y")}).ToArray()}});}
 internal static string Instructions(object value){var html=TougliReader.S(value);html=Regex.Replace(html,@"<img\b[^>]*\balt\s*=\s*""([^""]+)""[^>]*>",m=>m.Groups[1].Value=="quest"||m.Groups[1].Value=="item"?"":" [Illustration : "+WebUtility.HtmlDecode(m.Groups[1].Value)+"] ",RegexOptions.IgnoreCase,TimeSpan.FromSeconds(2));html=Regex.Replace(html,@"<li\b[^>]*>","\n• ",RegexOptions.IgnoreCase);var text=TougliReader.Plain(html);return Regex.Replace(text,@"\n[\t \r]*\n(?:[\t \r]*\n)+","\n\n").Trim();}
 internal static TougliDocument Parse(string json,string expectedSlug){if(!IsGuide(expectedSlug)||Encoding.UTF8.GetByteCount(json)>TougliReader.MaxBytes)throw new InvalidDataException("Guide Ganymède invalide.");var guide=TougliReader.Get(Json.DeserializeObject(json),"ganymedeGuide");if(guide==null||"ganymede-"+TougliReader.S(TougliReader.Get(guide,"id"))!=expectedSlug)throw new InvalidDataException("Ganymède a renvoyé un autre guide.");var title=TougliReader.Plain(TougliReader.Get(guide,"name"));if(title=="")throw new InvalidDataException("Titre de guide absent.");var author=TougliReader.Plain(TougliReader.Get(guide,"author"));var doc=new TougliDocument{Slug=expectedSlug,Title=title,Description="Source : Ganymède"+(author==""?"":" · "+author)+"\n"+Instructions(TougliReader.Get(guide,"description")),Hash=WorkspaceNext.Hash(Encoding.UTF8.GetBytes(json))};var steps=TougliReader.Arr(TougliReader.Get(guide,"steps"));if(steps.Length<1||steps.Length>10000)throw new InvalidDataException("Étapes Ganymède invalides.");var ids=new HashSet<string>();foreach(var s in steps.OrderBy(s=>{int n;return Int32.TryParse(TougliReader.S(TougliReader.Get(s,"order")),out n)?n:0;})){string id=TougliReader.S(TougliReader.Get(s,"id"));if(!Regex.IsMatch(id,@"^[1-9][0-9]{0,11}$")||!ids.Add(id))throw new InvalidDataException("Identifiant d’étape invalide.");var details=Instructions(TougliReader.Get(s,"text"));if(details.Length>60000)throw new InvalidDataException("Instructions trop longues.");var name=TougliReader.Plain(TougliReader.Get(s,"name"));int x,y;bool coordinates=TougliReader.Get(s,"pos_x")!=null&&TougliReader.Get(s,"pos_y")!=null&&Int32.TryParse(TougliReader.S(TougliReader.Get(s,"pos_x")),out x)&&Int32.TryParse(TougliReader.S(TougliReader.Get(s,"pos_y")),out y);string position=coordinates?TougliReader.S(TougliReader.Get(s,"pos_x"))+","+TougliReader.S(TougliReader.Get(s,"pos_y")):"";int number=doc.Steps.Count+1;doc.Steps.Add(new TougliStep{Key=expectedSlug+"/"+id+"/"+WorkspaceNext.Hash(Encoding.UTF8.GetBytes(details+"/"+position)).Substring(0,20),Title=name==""?"Étape "+number:name,Section=TougliReader.Plain(TougliReader.Get(s,"map"))+(position==""?"":" · ["+position+"]"),Details=details,Url=Url(expectedSlug)+"?page="+number+"&stepsPerPage=1",Coordinates=position,CanComplete=details!=""});}return doc;}
 internal static string Credit(TougliDocument doc){return doc!=null&&IsGuide(doc.Slug)?doc.Description.Split('\n')[0]:"Tougli — Toufloux et Gligo";}
}
